    mozilla::glean::mail::compact_duration.StopAndAccumulate(
        std::move(mTimerId));
    PROFILER_MARKER_TEXT(
        "FolderCompactor", MAILNEWS,
        mozilla::MarkerOptions(mozilla::MarkerTiming::IntervalEnd()),
        mFolder->URI());
  }

